class AMJ_Gebetstracker
{
    private const NONCE_ACTION = 'amj_gebetstracker';
    private const SHORTCODE = 'amj_gebetstracker';

    private array $prayers = [
        [
            'id' => 'fajr',
            'name' => 'Fajr',
            'time' => '06:30',
            'label' => 'Morgen',
        ],
        [
            'id' => 'zohr',
